template <class T> struct __mremove_cvref<const T &&> { typedef T type; };
template <class T> using __mremove_cvref_t = typename __mremove_cvref<T>::type;
template <class A, class B> struct __mis_same { static constexpr bool value = false; };
template <class A> struct __mis_same<A, A> { static constexpr bool value = true; };
template <class T> struct __mis_16f { static constexpr bool value = false; };
template <> struct __mis_16f<half> { static constexpr bool value = true; };
template <> struct __mis_16f<bfloat> { static constexpr bool value = true; };
// ---- vector constructors: float4(uv, 0, 1), float4(x), half3(v) ... ----
// (the checker rewrites  floatN( ... )  into  __mctor<floatN>( ... )  before clang sees it)
template <class V, class... A> constexpr V __mctor(A... a) {
  if constexpr (__mvi<V>::n == 1) { return V(a...); } else {
  using E = __elem_t<V>;
  constexpr int N = __len_v<V>;
  constexpr int total = (0 + ... + __len_v<A>);
  static_assert(sizeof...(A) == 0 || (sizeof...(A) == 1 && (total == 1 || total == N)) || total == N,
                "vector constructor: wrong number of components");
  V r{};
  if constexpr (sizeof...(A) == 1 && total == 1) {
    ((r = (V)(E)a), ...);
  } else {
    int i = 0;
    auto put = [&](auto x) {
      using X = decltype(x);
      if constexpr (__len_v<X> == 1) { if (i < N) r[i++] = (E)x; }
      else { for (int k = 0; k < __len_v<X> && i < N; k++) r[i++] = (E)x[k]; }
    };
    (put(a), ...);
  }
  return r;
  }
}
// static_cast the way Metal converts: bfloat <-> half through float, vectors element by element
template <class T, class X> constexpr T __mscast(X &&x) {
  using D = __mremove_cvref_t<X>;
  if constexpr (__mvi<__mremove_cvref_t<T>>::n > 1 && __mvi<D>::n > 1 && !__mis_same<__mremove_cvref_t<T>, D>::value) {
    using V = __mremove_cvref_t<T>;
    V r{}; for (int i = 0; i < __mvi<V>::n && i < __mvi<D>::n; i++) r[i] = (__elem_t<V>)(float)x[i]; return r;
  } else if constexpr (__mis_16f<__mremove_cvref_t<T>>::value && __mis_16f<D>::value && !__mis_same<__mremove_cvref_t<T>, D>::value) {
    return (T)(float)x;
  } else {
    return static_cast<T>(static_cast<X &&>(x));
  }
}
// Metal's converting cast: (half4)float4_value, (float)half_value, (float4x4)half4x4_value
template <class V, class X> constexpr V __mcvt(X x) {
  if constexpr (__mvi<V>::n == 1) { return (V)x; }
  else if constexpr (__mvi<X>::n == 1) { return (V)(__elem_t<V>)x; }
  else {
    static_assert(__mvi<X>::n == __mvi<V>::n, "vector conversion: different number of components");
    V r{}; for (int i = 0; i < __mvi<V>::n; i++) r[i] = (__elem_t<V>)x[i]; return r;
  }
}


// ---- matrices: floatCxR (C columns of R rows) ----
template <class T, int C, int R> struct matrix {
  vec<T, R> columns[C];
  constexpr matrix() : columns{} {}
  constexpr matrix(T d) : columns{} { for (int i = 0; i < C && i < R; i++) columns[i][i] = d; }
  template <class... A> constexpr matrix(A... a) : columns{} {
    if constexpr (sizeof...(A) == C) { int i = 0; ((columns[i++] = (vec<T, R>)a), ...); }
    else { T s[] = {(T)a...}; static_assert(sizeof...(A) == C * R, "matrix constructor: wrong number of values");
           for (int c = 0; c < C; c++) for (int r = 0; r < R; r++) columns[c][r] = s[c * R + r]; } }
  template <class U> constexpr matrix(const matrix<U, C, R> &o) : columns{} {
    for (int c = 0; c < C; c++) for (int r = 0; r < R; r++) columns[c][r] = (T)o.columns[c][r]; }
  constexpr vec<T, R> &operator[](int i) { return columns[i]; }
  constexpr vec<T, R> operator[](int i) const { return columns[i]; }
};
template <class T, int C, int R> constexpr matrix<T, C, R> operator+(matrix<T, C, R> a, matrix<T, C, R> b) { for (int c = 0; c < C; c++) a.columns[c] += b.columns[c]; return a; }
template <class T, int C, int R> constexpr matrix<T, C, R> operator-(matrix<T, C, R> a, matrix<T, C, R> b) { for (int c = 0; c < C; c++) a.columns[c] -= b.columns[c]; return a; }
template <class T, int C, int R> constexpr matrix<T, C, R> operator*(matrix<T, C, R> a, T s) { for (int c = 0; c < C; c++) a.columns[c] *= s; return a; }
template <class T, int C, int R> constexpr matrix<T, C, R> operator*(T s, matrix<T, C, R> a) { return a * s; }
template <class T, int C, int R> constexpr vec<T, R> operator*(matrix<T, C, R> m, vec<T, C> v) { vec<T, R> r{}; for (int c = 0; c < C; c++) r += m.columns[c] * v[c]; return r; }
template <class T, int C, int R> constexpr vec<T, C> operator*(vec<T, R> v, matrix<T, C, R> m) { vec<T, C> r{}; for (int c = 0; c < C; c++) { T s = 0; for (int k = 0; k < R; k++) s += v[k] * m.columns[c][k]; r[c] = s; } return r; }
template <class T, int K, int C, int R> constexpr matrix<T, C, R> operator*(matrix<T, K, R> a, matrix<T, C, K> b) { matrix<T, C, R> r; for (int c = 0; c < C; c++) r.columns[c] = a * b.columns[c]; return r; }
template <class T, int C, int R> constexpr matrix<T, C, R> &operator*=(matrix<T, C, R> &a, T s) { return a = a * s; }
template <class T, int C, int R> constexpr matrix<T, C, R> &operator+=(matrix<T, C, R> &a, matrix<T, C, R> b) { return a = a + b; }

